import {fit,tokens,cosine,angle,profile,rank,contributions,norm,validateEmbeddings} from './engine.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(n,d=3)=>n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const degrees=n=>number(n,1)+'°';
let movies=[],tfidf,engine,embedding,watched=[],demo=true,page=1,step=0,aId='m001',bId='m002',timer;
const pageSize=24;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function save(){try{localStorage.setItem('cinevetor-v1',JSON.stringify({watched,demo:false}));}catch{toast('Histórico disponível nesta sessão; o navegador bloqueou o armazenamento.');}}
function movie(id){return movies.find(m=>m.id===id);}
function card(m,result){const selected=watched.includes(m.id);return `<article class="movie-card"><button class="poster-button" data-details="${m.id}" aria-label="Ver detalhes de ${esc(m.title)} (${m.year})"><img loading="lazy" src="assets/${m.id}.svg" alt="Capa editorial: ${esc(m.title)}" width="300" height="440">${result?`<span class="angle-badge" title="Ângulo em relação ao perfil">${degrees(result.angle)}</span>`:''}</button><h3>${esc(m.title)}</h3><p class="movie-meta">${m.year} · ${esc(m.theme)}</p><div class="card-bottom"><button class="text-button" data-details="${m.id}">${result?'Por que este filme?':'Ver descrição'}</button><button class="watch-button ${selected?'selected':''}" data-watch="${m.id}" aria-pressed="${selected}" aria-label="${selected?'Remover':'Adicionar'} ${esc(m.title)} (${m.year}) ${selected?'do':'ao'} histórico">${selected?'✓ Visto':'+ Visto'}</button></div></article>`;}
function renderHistory(){
 $('#history-count').textContent=watched.length;
 $('#history-caption').textContent=demo?'Exemplo inicial: Matrix. Troque pelos seus favoritos.':'Filmes que você assistiu e gostou. Todos têm o mesmo peso.';
 $('#history-list').innerHTML=watched.length?watched.map(id=>{const m=movie(id);return `<div class="history-item"><img src="assets/${id}.svg" alt="" width="40" height="58"><div><strong>${esc(m.title)}</strong><small>${m.year}</small></div><button data-watch="${id}" aria-label="Remover ${esc(m.title)} do histórico">×</button></div>`;}).join(''):'<p class="small muted">Seu histórico está vazio. Escolha um filme para começar.</p>';
 $('#clear-history').disabled=!watched.length;
 const results=rank(engine,watched,movies);
 $('#recommendations').innerHTML=results.length?`<div class="recommendation-grid">${results.slice(0,4).map(r=>card(r.movie,r)).join('')}</div>`: `<div class="empty"><strong>${watched.length===movies.length?'Você já selecionou todo o catálogo.':'A próxima sessão começa com uma escolha.'}</strong>${watched.length===movies.length?'Remova um favorito para que ele volte a ser candidato.':'Adicione um filme de que gostou ou experimente um dos perfis acima.'}<br><a class="button primary" href="#catalogo">Explorar filmes</a></div>`;
 $('#engine-label').textContent=`${engine.kind==='tfidf'?'TF-IDF · descrições em português':'Embeddings · '+engine.model} · ranking por menor ângulo`;
}
function filtered(){const q=$('#search').value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const theme=$('#theme').value,decade=$('#decade').value;return movies.filter(m=>(!theme||m.theme===theme)&&(!decade||Math.floor(m.year/10)*10===Number(decade))&&(!q||(m.title+' '+m.description).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q)));}
function renderCatalog(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(page,pages);$('#catalog-count').textContent=`${rows.length} de ${movies.length} filmes`;$('#catalog-grid').innerHTML=rows.length?rows.slice((page-1)*pageSize,page*pageSize).map(m=>card(m)).join(''):'<div class="empty"><strong>Nenhum filme encontrado.</strong>Tente outro título ou limpe os filtros.</div>';$('#pagination-label').textContent=`Página ${page} de ${pages}`;$('#previous').disabled=page===1;$('#next').disabled=page===pages;}
function comparison(){const ai=movies.findIndex(m=>m.id===aId),bi=movies.findIndex(m=>m.id===bId);const a=aId==='profile'?profile(engine,watched,movies):engine.vectors[ai];const b=engine.vectors[bi];return {a,b,ai,bi,aName:aId==='profile'?'Seu histórico':movie(aId)?.title,bName:movie(bId)?.title};}
function renderLab(){
 const c=comparison();
 if(!c.a||!norm(c.a)){ $('#comparison').innerHTML='<div class="empty"><strong>O histórico ainda não tem um vetor válido.</strong>Adicione um filme ou escolha um título no seletor Vetor A.</div>';renderStep();return; }
 const s=cosine(c.a,c.b),theta=angle(s),rad=theta*Math.PI/180,x=250+190*Math.cos(rad),y=235-190*Math.sin(rad),ax=250+65*Math.cos(rad),ay=235-65*Math.sin(rad);
 const common=engine.kind==='tfidf'?contributions(c.a,c.b,tfidf.vocab):[];
 $('#comparison').innerHTML=`<div class="comparison-grid"><div class="angle-panel"><p class="eyebrow">O ÂNGULO ENTRE OS VETORES</p><svg viewBox="0 0 500 290" role="img" aria-label="Ângulo de ${degrees(theta)} entre ${esc(c.aName)} e ${esc(c.bName)}"><path d="M45 235H460M250 25V250" stroke="#3c4838" stroke-width="1"/><path d="M60 235 A190 190 0 0 1 440 235" stroke="#34462c" fill="none" stroke-dasharray="4 7"/><path d="M250 235H440" stroke="#c2f18c" stroke-width="4"/><circle cx="440" cy="235" r="5" fill="#c2f18c"/><path d="M250 235L${x} ${y}" stroke="#e7bb8d" stroke-width="4"/><circle cx="${x}" cy="${y}" r="5" fill="#e7bb8d"/><path d="M315 235A65 65 0 ${theta>180?1:0} 0 ${ax} ${ay}" stroke="#c2f18c" stroke-width="1.5" fill="none"/><circle cx="250" cy="235" r="5" fill="#ecf3e6"/><text x="250" y="278" fill="#a4afa3" text-anchor="middle" font-size="14">origem</text><text x="445" y="258" fill="#c2f18c" font-size="15">A</text><text x="${x+10}" y="${y-10}" fill="#e7bb8d" font-size="15">B</text><text x="253" y="120" fill="#c2f18c" font-size="38" font-family="Georgia">${degrees(theta)}</text></svg><div class="legend"><span>Vetor A</span><span>Vetor B</span></div><p class="angle-explainer">Desenho em 2D construído para preservar o ângulo calculado no espaço de ${engine.vectors[0].length} dimensões. Os eixos não representam palavras.</p></div><div class="math-panel"><div class="metric-row"><div><strong>${degrees(theta)}</strong><small>ângulo · menor é mais próximo</small></div><div><strong>${number(s)}</strong><small>similaridade · cos(θ)</small></div><div><strong>${number(1-s)}</strong><small>distância · 1 − cos(θ)</small></div></div><h3>O mesmo cálculo, três maneiras de ler</h3><div class="math-formula">θ = arccos(${number(s,4)}) ≈ ${degrees(theta)}</div><p class="small muted">Vetores normalizados: ||A|| = ${number(norm(c.a))} e ||B|| = ${number(norm(c.b))}. O produto escalar A · B = ${number(s,6)} já é a similaridade. Exibimos valores arredondados; o ranking usa a precisão completa.</p><h3>${engine.kind==='tfidf'?'Palavras que aproximam':'Uma representação semântica'}</h3><div class="term-chips">${common.slice(0,6).map(t=>`<span>${esc(t.term)}</span>`).join('')}</div><p class="small muted">${engine.kind==='tfidf'?(common.length?'Veja a contribuição de cada termo na etapa “Vetores”.':'Sem termos compartilhados após o processamento: cosseno 0 e ângulo 90°. Isso não prova que os enredos não tenham relação semântica.'):'As dimensões do Transformer são características aprendidas. Não atribuímos palavras diretamente a elas.'}</p></div></div>`;
 renderStep();
}
function renderStep(){
 $$('.step-tabs button').forEach((b,i)=>{b.setAttribute('aria-selected',i===step);b.tabIndex=i===step?0:-1;});$('#step-content').setAttribute('aria-labelledby','tab-'+step);
 const c=comparison(),selected=aId==='profile'?watched.map(movie):[movie(aId)],textsA=selected.map(m=>`<b>${esc(m.title)} (${m.year})</b><div class="description-box">${esc(m.description)}</div>`).join('')||'<p>Histórico vazio.</p>',b=movie(bId);
 let content='';
 if(step===0)content=`<h3>A entrada é o texto</h3><p>Título, ano e tema ajudam a navegar, mas somente estas descrições entram na representação.</p><div class="two-columns"><div><p class="eyebrow">VETOR A · ${esc(c.aName)}</p>${textsA}</div><div><p class="eyebrow">VETOR B · ${esc(c.bName)}</p><b>${esc(b.title)} (${b.year})</b><div class="description-box">${esc(b.description)}</div></div></div>`;
 if(step===1){content=engine.kind==='embedding'?'<h3>Tokenização do Transformer</h3><p>O script Python usa o tokenizer do modelo, com subpalavras, máscara de atenção e truncamento conforme a configuração do modelo. Os tokens do TF-IDF não são usados nos embeddings. Textos maiores que o limite do modelo podem perder informação.</p>':`<h3>Remover ruído, manter termos</h3><p>Minúsculas, sem acentos nem pontuação. Removemos stopwords e tokens com até dois caracteres. Não há lematização ou agrupamento oculto de sinônimos.</p><div class="two-columns"><div><b>${esc(c.aName)}</b>${selected.map(m=>`<p class="small">${esc(m.title)}</p><div class="term-chips">${tokens(m.description).map(t=>`<span>${esc(t)}</span>`).join('')}</div>`).join('')}</div><div><b>${esc(c.bName)}</b><div class="term-chips">${tokens(b.description).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div>`;}
 if(step===2){
 if(!c.a)content='<p>Escolha filmes para gerar um perfil.</p>';
 else if(engine.kind==='embedding')content=`<h3>${engine.vectors[0].length} dimensões aprendidas</h3><p>Modelo informado pelo arquivo: <b>${esc(engine.model)}</b>. Vetores normalizados. As dimensões não são palavras. A soma de todos os produtos é ${number(cosine(c.a,c.b),6)}.</p><div class="table-wrap"><table><thead><tr><th>Dimensão</th><th>A</th><th>B</th><th>A × B</th></tr></thead><tbody>${c.a.slice(0,12).map((a,i)=>`<tr><td>${i+1}</td><td>${number(a,5)}</td><td>${number(c.b[i],5)}</td><td>${number(a*c.b[i],6)}</td></tr>`).join('')}</tbody></table></div><p>Exibidas as primeiras 12 dimensões. Produtos negativos também participam da soma.</p>`;
 else{const shared=contributions(c.a,c.b,tfidf.vocab),indices=shared.length?shared.slice(0,12).map(t=>t.index):tfidf.vocab.map((_,i)=>i).filter(i=>c.a[i]||c.b[i]).sort((i,j)=>(c.a[j]+c.b[j])-(c.a[i]+c.b[i])).slice(0,12),sum=indices.reduce((acc,i)=>acc+c.a[i]*c.b[i],0),score=cosine(c.a,c.b);
 content=`<h3>${tfidf.vocab.length} termos, um espaço compartilhado</h3><p>TF = contagem. IDF = ln((1 + ${movies.length}) / (1 + df)) + 1. A e B mostram pesos após normalização L2. ${aId==='profile'?'A é a média normalizada do histórico; não possui uma contagem TF única.':'A soma dos quadrados de cada vetor normalizado é 1.'}</p><div class="table-wrap"><table><thead><tr><th>Termo</th><th>df</th><th>IDF</th><th>TF em A</th><th>TF em B</th><th>Peso A</th><th>Peso B</th><th>A × B</th></tr></thead><tbody>${indices.map(i=>`<tr><td>${esc(tfidf.vocab[i])}</td><td>${tfidf.df[i]}</td><td>${number(tfidf.idf[i])}</td><td>${aId==='profile'?'—':tfidf.counts[c.ai][i]}</td><td>${tfidf.counts[c.bi][i]}</td><td>${number(c.a[i],4)}</td><td>${number(c.b[i],4)}</td><td>${number(c.a[i]*c.b[i],6)}</td></tr>`).join('')}</tbody></table></div><p>Contribuição das linhas exibidas: <b>${number(sum,6)}</b>. Demais dimensões: <b>${number(Math.max(0,score-sum),6)}</b>. Soma completa (cosseno): <b>${number(score,6)}</b>. ${shared.length?'Termos ordenados pela contribuição ao produto escalar.':'Não há termos em comum; mostramos termos presentes em pelo menos um vetor.'}</p>`;}
 }
 if(step===3){const p=profile(engine,watched,movies);content=`<h3>Uma média dos seus favoritos</h3><p>Somamos os vetores normalizados dos ${watched.length} filmes do histórico, dividimos por ${watched.length||'k'} e normalizamos o resultado. O perfil dá peso igual a cada favorito. A comparação acima só usa esse perfil quando o Vetor A está em “Meu histórico”.</p><code>perfil = normalizar(média(vetores dos filmes vistos))</code><div class="term-chips">${watched.map(id=>`<span>${esc(movie(id).title)}</span>`).join('')}</div>${p&&engine.kind==='tfidf'?`<p>Maiores componentes do perfil:</p><div class="term-chips">${p.map((x,i)=>({x,t:tfidf.vocab[i]})).sort((a,b)=>b.x-a.x).slice(0,10).map(t=>`<span>${esc(t.t)} · ${number(t.x)}</span>`).join('')}</div>`:''}<p>Mais filmes não garantem melhor recomendação. Preferências diferentes podem se diluir na média; um sistema real pode manter perfis separados por interesse.</p><button class="button secondary" data-use-profile>Comparar usando meu histórico</button>`;}
 if(step===4){const rows=rank(engine,watched,movies);content=`<h3>Menor ângulo primeiro</h3><p>Este ranking usa sempre o histórico atual, independentemente do par selecionado acima. Exclui vistos e ordena por similaridade decrescente; empates usam o ID.</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Posição</th><th>Filme</th><th>Ângulo</th><th>Cosseno</th><th>Distância</th><th>Comparar</th></tr></thead><tbody>${rows.slice(0,10).map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.movie.title)} (${r.movie.year})</td><td>${degrees(r.angle)}</td><td>${number(r.score,4)}</td><td>${number(r.distance,4)}</td><td><button class="text-button" data-compare="${r.movie.id}">Inspecionar</button></td></tr>`).join('')}</tbody></table></div><p>${rows.length} candidatos no total. O CSV inclui todos, com seis casas decimais.</p>`:'<p>Não há candidatos. Escolha favoritos ou remova filmes do histórico.</p>'}`;}
 $('#step-content').innerHTML=content;
}
function updateHistory(){demo=false;save();renderHistory();renderCatalog();renderLab();}
function toggle(id){if(!movie(id))return;watched=watched.includes(id)?watched.filter(x=>x!==id):[...watched,id];updateHistory();toast(watched.includes(id)?'Filme adicionado. Recomendações recalculadas.':'Filme removido. Recomendações recalculadas.');if($('#movie-dialog').open)showDetails(id);}
function showDetails(id){const m=movie(id),result=rank(engine,watched,movies).find(r=>r.movie.id===id),p=profile(engine,watched,movies),i=movies.findIndex(m=>m.id===id);const terms=p&&engine.kind==='tfidf'?contributions(p,engine.vectors[i],tfidf.vocab).slice(0,6):[];$('#dialog-content').innerHTML=`<div class="dialog-grid"><img src="assets/${id}.svg" alt="Capa editorial de ${esc(m.title)}"><div><p class="eyebrow">${m.year} · ${esc(m.theme)}</p><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p>${result?`<p><b>${degrees(result.angle)}</b> em relação ao seu histórico · cosseno ${number(result.score)}</p><div class="term-chips">${terms.map(t=>`<span>${esc(t.term)}</span>`).join('')}</div><p class="small">${engine.kind==='tfidf'?(terms.length?'Estes termos contribuem para aproximar a descrição do seu perfil.':'Nenhum termo em comum com o perfil. Este modelo lexical não identificou alinhamento.'):'Comparação semântica com os embeddings importados.'}</p>`:'<p class="small">'+(watched.includes(id)?'Este filme está no histórico e não entra no ranking.':'Adicione favoritos para comparar este filme com seu perfil.')+'</p>'}<div class="dialog-actions"><button class="button primary" data-watch="${id}">${watched.includes(id)?'Remover do histórico':'Já vi e gostei'}</button><button class="button secondary" data-compare="${id}">Inspecionar cálculo</button></div></div></div>`;if(!$('#movie-dialog').open)$('#movie-dialog').showModal();}
function route(){const hash=location.hash.slice(1)||'descobrir';const target=['laboratorio','como-funciona','projeto'].includes(hash)?hash:'descobrir';$$('.page').forEach(s=>s.hidden=s.id!==target);$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===target);if(a.dataset.nav===target)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(hash==='catalogo')requestAnimationFrame(()=>$('#catalogo').scrollIntoView());else window.scrollTo(0,0);}
function compareWith(id){aId=watched.length?'profile':'m001';bId=id;$('#compare-a').value=aId;$('#compare-b').value=bId;step=2;renderLab();$('#movie-dialog').close();location.hash='laboratorio';}
function exportRanking(){const rows=rank(engine,watched,movies);if(!rows.length){toast('Adicione favoritos para gerar um ranking.');return;}const quote=s=>'"'+String(s).replaceAll('"','""')+'"';const lines=[['posição','id','filme','ano','ângulo_graus','similaridade','distância','representação','histórico'].map(quote).join(';'),...rows.map((r,i)=>[i+1,r.movie.id,r.movie.title,r.movie.year,number(r.angle,6),number(r.score,6),number(r.distance,6),engine.kind==='tfidf'?'TF-IDF':engine.model,watched.join(',')].map(quote).join(';'))];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='cinevetor-ranking.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function init(){
 const response=await fetch('movies.json');if(!response.ok)throw Error('Não foi possível abrir o catálogo.');movies=await response.json();tfidf=fit(movies);engine=tfidf;
 try{const saved=JSON.parse(localStorage.getItem('cinevetor-v1'));if(saved&&Array.isArray(saved.watched)){watched=[...new Set(saved.watched)].filter(id=>movie(id));demo=false;}else watched=['m001'];}catch{watched=['m001'];}
 const options=movies.map(m=>`<option value="${m.id}">${esc(m.title)} (${m.year})</option>`).join('');$('#compare-a').innerHTML='<option value="profile">Meu histórico · média dos favoritos</option>'+options;$('#compare-b').innerHTML=options;$('#compare-a').value=aId;$('#compare-b').value=bId;
 $('#theme').innerHTML+=[...new Set(movies.map(m=>m.theme))].map(t=>`<option>${esc(t)}</option>`).join('');
 renderHistory();renderCatalog();renderLab();route();
 document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.watch)toggle(t.dataset.watch);if(t.dataset.details)showDetails(t.dataset.details);if(t.dataset.compare)compareWith(t.dataset.compare);if(t.hasAttribute('data-use-profile')){aId='profile';$('#compare-a').value=aId;renderLab();$('#comparison').scrollIntoView({block:'start'});}if(t.dataset.step!==undefined){step=Number(t.dataset.step);renderStep();}if(t.dataset.preset){const names={matrix:'Matrix',space:'Interestelar',aviation:'Top Gun: Ases Indomáveis',romance:'Antes do Amanhecer'};watched=[movies.find(m=>m.title===names[t.dataset.preset]).id];updateHistory();toast('Perfil de exemplo aplicado. Explore as novas recomendações.');}});
 $('#add-movie').onclick=()=>{location.hash='catalogo';$('#search').focus({preventScroll:true});};
 $('#clear-history').onclick=()=>{watched=[];updateHistory();toast('Histórico apagado neste navegador.');};
 for(const id of ['search','theme','decade'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=1;renderCatalog();});
 $('#reset-filters').onclick=()=>{for(const id of ['search','theme','decade'])$('#'+id).value='';page=1;renderCatalog();};
 $('#previous').onclick=()=>{page--;renderCatalog();$('#catalogo').scrollIntoView();};$('#next').onclick=()=>{page++;renderCatalog();$('#catalogo').scrollIntoView();};
 $('#compare-a').onchange=e=>{aId=e.target.value;renderLab();};$('#compare-b').onchange=e=>{bId=e.target.value;renderLab();};
 $('.dialog-close').onclick=()=>$('#movie-dialog').close();$('#movie-dialog').onclick=e=>{if(e.target===$('#movie-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
 $('.step-tabs').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();step=e.key==='Home'?0:e.key==='End'?4:(step+(e.key==='ArrowRight'?1:4))%5;renderStep();$('#tab-'+step).focus();}};
 $('#export-ranking').onclick=exportRanking;
 $('#same-vector').onclick=()=>{if(aId==='profile'){aId=watched[0]||'m001';$('#compare-a').value=aId;}bId=aId;$('#compare-b').value=bId;renderLab();};
 $('#orthogonal-vector').onclick=()=>{engine=tfidf;$('#engine-select').value='tfidf';$('#embedding-status').textContent='Modo atual: TF-IDF.';if(aId==='profile'){aId=watched[0]||'m001';$('#compare-a').value=aId;}const ai=movies.findIndex(m=>m.id===aId);const bi=tfidf.vectors.findIndex(v=>cosine(tfidf.vectors[ai],v)===0);if(bi>=0){bId=movies[bi].id;$('#compare-b').value=bId;renderHistory();renderLab();}else toast('Este filme compartilha termos com todos os outros. Escolha outro vetor A.');};
 $('#embedding-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>25*1024*1024)throw Error('Use um arquivo JSON com até 25 MB.');const data=JSON.parse(await file.text());embedding=validateEmbeddings(data,movies);engine=embedding;if(!$('#engine-select option[value="embedding"]'))$('#engine-select').insertAdjacentHTML('beforeend','<option value="embedding">Transformer · embeddings importados</option>');$('#engine-select').value='embedding';$('#embedding-status').textContent='Carregado: '+embedding.model+'. '+embedding.vectors[0].length+' dimensões; processado neste navegador.';renderHistory();renderLab();toast('Embeddings validados e ranking recalculado.');}catch(error){$('#embedding-status').textContent=error.message;toast('Não foi possível usar os embeddings.');}e.target.value='';};
 $('#engine-select').onchange=e=>{engine=e.target.value==='embedding'&&embedding?embedding:tfidf;$('#embedding-status').textContent=engine.kind==='tfidf'?'Modo atual: TF-IDF. Embeddings não participam do cálculo.':'Modo atual: '+engine.model;renderHistory();renderLab();};
 addEventListener('hashchange',route);
}
init().catch(error=>{console.error(error);$('#recommendations').innerHTML='<div class="empty"><strong>Não foi possível carregar o site.</strong>Execute por um servidor HTTP (veja o README), verifique a conexão e recarregue.</div>';toast('Erro ao carregar o catálogo.');});
